const appCSS = `:root{--bg:#0d1117;--panel:#161b22;--text:#e6edf3;--muted:#8b949e;--border:#30363d;--accent:#58a6ff}*{box-sizing:border-box}body{margin:0;font-family:system-ui,sans-serif;background:var(--bg);color:var(--text)}.layout{display:flex;height:100vh}aside{width:300px;background:var(--panel);border-right:1px solid var(--border);padding:1rem;overflow-y:auto;flex-shrink:0}aside h1{font-size:1rem;margin:0 0 .35rem}aside h2{font-size:.85rem;color:var(--muted);margin:1rem 0 .5rem;text-transform:uppercase;letter-spacing:.05em}#map-wrap{flex:1;min-height:0;position:relative}#map{width:100%;height:100%}.sub{color:var(--muted);font-size:.8rem;margin-bottom:1rem}.brand-nav{margin:0 0 .7rem}.sub a,a{color:var(--accent)}.poll-row{display:flex;align-items:center;justify-content:space-between;gap:.55rem;margin:0 0 .9rem}.poll-label{font-size:.68rem;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);flex-shrink:0}.seg{display:inline-flex;border:1px solid var(--border);border-radius:999px;overflow:hidden;background:#0d111759}.seg-btn{appearance:none;border:0;background:transparent;color:var(--muted);font:inherit;font-size:.72rem;font-variant-numeric:tabular-nums;padding:.22rem .62rem;cursor:pointer;line-height:1.25}.seg-btn+.seg-btn{border-left:1px solid var(--border)}.seg-btn:hover{color:var(--text)}.seg-btn.active{color:var(--accent);background:#58a6ff1f;font-weight:600}.stats p{margin:.35rem 0;font-size:.9rem}.stats span{font-weight:600}.status{font-size:.8rem;color:var(--muted);margin-top:.5rem}.status.ok{color:#3fb950}.status.err,.empty-msg{color:#f85149}.region-btn{display:block;width:100%;text-align:left;margin:.2rem 0;padding:.45rem .6rem;border:1px solid var(--border);border-radius:6px;background:transparent;color:var(--text);cursor:pointer;font-size:.85rem}.region-btn.active{border-color:var(--accent);background:#58a6ff1f}.tenant-list{font-size:.8rem;color:var(--muted);margin:0;padding-left:1rem}.tenant-list li{margin:.15rem 0}.debug-toggle{font-size:.8rem;margin-top:1rem}.poll-button{width:100%;margin-top:1rem;padding:.55rem .6rem;border:1px solid var(--accent);border-radius:6px;background:#58a6ff1f;color:var(--text);cursor:pointer;font-weight:600}.poll-button:disabled{opacity:.5;cursor:wait}.controls{display:flex;gap:.35rem;flex-wrap:wrap}.controls button,.controls select{font-size:.8rem;padding:.35rem .5rem;border-radius:6px;border:1px solid var(--border);background:var(--panel);color:var(--text);cursor:pointer}.controls button:disabled{opacity:.5;cursor:not-allowed}.catalog-agency{margin-bottom:.75rem;font-size:.8rem}.catalog-agency h3{margin:0 0 .25rem;font-size:.8rem}.muted,.notes{color:var(--muted)}.snap-row{font-family:ui-monospace,monospace;font-size:.68rem;color:var(--muted);margin:.1rem 0}.notes{font-size:.7rem;padding-left:1rem}.notes li{margin:.2rem 0}#ingest-overlay{display:none;position:absolute;right:8px;bottom:8px;max-width:360px;max-height:40vh;overflow:auto;background:#0d1117d1;border:1px solid var(--border);border-radius:6px;padding:.5rem .65rem;font:.68rem/1.35 ui-monospace,monospace;color:var(--muted);z-index:1000;pointer-events:none}#ingest-overlay.visible{display:block}`

const appJS = `(() => {
  const config=window.SITE_CONFIG, first=config.regions[0], ALLOWED_POLL=[10,20,30];
  const map=L.map('map',{preferCanvas:true}).setView(first.center,first.zoom);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap',maxZoom:19}).addTo(map);
  setTimeout(()=>map.invalidateSize(),100);
  const markers={},status=document.getElementById('stream-status'),overlay=document.getElementById('ingest-overlay'),debug=document.getElementById('debug-ingest'),pollButton=document.getElementById('poll-now'),pollStatus=document.getElementById('poll-status');
  let active=first,agencies=new Set(first.agencies),pollInFlight=false,pollSeconds=10,pollTimer=null;
  const region=id=>config.regions.find(r=>r.id===id)||first;
  function renderRegions(){document.getElementById('region-list').innerHTML=config.regions.map(r=>'<button class="region-btn '+(r.id===active.id?'active':'')+'" data-region="'+r.id+'">'+r.label+'</button>').join('');document.querySelectorAll('.region-btn').forEach(b=>b.onclick=()=>switchRegion(b.dataset.region))}
  function renderFeeds(){document.getElementById('tenant-list').innerHTML=config.feeds.filter(f=>agencies.has(f.agency)).map(f=>'<li>'+f.region+' <span style="opacity:.7">('+f.agency+')</span></li>').join('');document.getElementById('region-subtitle').textContent=active.label}
  function renderPoll(){document.querySelectorAll('#poll-interval .seg-btn').forEach(btn=>{const on=Number(btn.getAttribute('data-poll'))===pollSeconds;btn.classList.toggle('active',on);btn.setAttribute('aria-checked',on?'true':'false')})}
  function schedulePoll(){if(pollTimer)clearInterval(pollTimer);pollTimer=setInterval(()=>{if(!document.hidden)void pollGTFS(false)},pollSeconds*1000)}
  function update(v){let m=markers[v.id],popup='<strong>'+v.agency+'</strong><br>Route: '+(v.route||'—')+'<br>Speed: '+Number(v.speed||0).toFixed(1)+' km/h';if(m)m.setLatLng([v.lat,v.lng]).setPopupContent(popup);else{m=markers[v.id]=L.circleMarker([v.lat,v.lng],{radius:7,color:'#3498db',fillColor:'#3498db',fillOpacity:.9,weight:2}).bindPopup(popup);m._agency=v.agency}if(agencies.has(v.agency)&&!map.hasLayer(m))m.addTo(map)}
  function apply(list){const seen=new Set(list.map(v=>v.id));list.forEach(update);Object.keys(markers).forEach(id=>{if(!seen.has(id)&&map.hasLayer(markers[id]))map.removeLayer(markers[id])});document.getElementById('vehicle-count').textContent=list.length;status.textContent='Live — '+list.length+' vehicles';status.className='status ok'}
  function ingestView(d){if(!debug.checked)return;overlay.className='visible';const polled=(d.polledAgencies||[]).filter(Boolean);overlay.innerHTML='<strong>Ingest — '+(d.activeLabel||active.label)+'</strong>'+(polled.length?'<br>polled: '+polled.join(', '):'')+'<br>'+((d.records&&d.records.length)?d.records.map(r=>r.agency+' '+r.vehicle+' '+Number(r.lat).toFixed(2)+','+Number(r.lng).toFixed(2)+' '+r.at).join('<br>'):'no ingest yet for this region')}
  function applyStats(d){document.getElementById('last-update').textContent=d.lastUpdate||'—';document.getElementById('event-count').textContent=d.eventCount||0;if(d.pollSeconds&&ALLOWED_POLL.includes(d.pollSeconds)&&d.pollSeconds!==pollSeconds){pollSeconds=d.pollSeconds;renderPoll();schedulePoll()}ingestView(d)}
  async function refreshVehicles(){const [vehiclesRes,statsRes]=await Promise.all([fetch('/api/vehicles'),fetch('/api/status')]);if(!vehiclesRes.ok||!statsRes.ok)throw new Error('projection refresh failed');apply(await vehiclesRes.json());applyStats(await statsRes.json());status.textContent='Live';status.className='status ok'}
  async function pollGTFS(force){if(pollInFlight||(!force&&document.hidden))return;pollInFlight=true;pollButton.disabled=true;pollStatus.textContent=force?'Calling GTFS feeds…':'Refreshing…';pollStatus.className='status';try{const res=await fetch(force?'/api/poll?force=1':'/api/poll',{method:'POST'}),data=await res.json();if(!res.ok)throw new Error(data.error||'poll failed');if(data.skipped){pollStatus.textContent='Fresh — skipped GTFS ('+pollSeconds+'s window)';pollStatus.className='status ok'}else{const failures=data.errors&&data.errors.length?' · '+data.errors.length+' feed errors':'';pollStatus.textContent='GTFS → R2: '+data.accepted+' positions ('+data.feeds+' feeds)'+failures+(data.r2Key?' · '+data.r2Key:'');pollStatus.className=data.errors&&data.errors.length?'status err':'status ok'}await refreshVehicles()}catch(e){pollStatus.textContent='GTFS poll failed: '+e.message;pollStatus.className='status err';status.textContent='Refresh failed';status.className='status err'}finally{pollInFlight=false;pollButton.disabled=false}}
  async function setPollInterval(seconds){if(seconds===pollSeconds)return;const prev=pollSeconds;pollSeconds=seconds;renderPoll();try{const res=await fetch('/api/poll-interval',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({seconds:seconds})});if(!res.ok)throw new Error(await res.text());const data=await res.json();pollSeconds=data.seconds;renderPoll();schedulePoll()}catch(e){pollSeconds=prev;renderPoll();status.textContent='Could not change refresh rate';status.className='status err'}}
  async function switchRegion(id){const r=region(id),res=await fetch('/api/region',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({id:id})});if(!res.ok)return;active=r;agencies=new Set(r.agencies);const payload=await res.json();if(payload.pollSeconds){pollSeconds=payload.pollSeconds;renderPoll();schedulePoll()}renderRegions();renderFeeds();map.flyTo(r.center,r.zoom,{duration:1});try{await pollGTFS(false)}catch(e){status.textContent='Refresh failed';status.className='status err'}}
  pollButton.onclick=()=>{void pollGTFS(true)};document.querySelectorAll('#poll-interval .seg-btn').forEach(btn=>btn.onclick=()=>setPollInterval(Number(btn.getAttribute('data-poll'))));debug.onchange=()=>{try{sessionStorage.setItem('debugIngest',debug.checked?'1':'0')}catch(e){}overlay.classList.toggle('visible',debug.checked);if(!debug.checked)overlay.innerHTML=''};try{if(sessionStorage.getItem('debugIngest')==='1'){debug.checked=true;overlay.classList.add('visible')}}catch(e){}document.addEventListener('visibilitychange',()=>{if(!document.hidden)void pollGTFS(false)});renderRegions();renderFeeds();renderPoll();schedulePoll();setTimeout(()=>{void pollGTFS(false)},150);
})()`

const replayJS = `(() => {
  const config=window.SITE_CONFIG,first=config.regions[0],map=L.map('map',{preferCanvas:true}).setView(first.center,first.zoom);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(map);const markers={};let current=first.id,source;
  const region=id=>config.regions.find(r=>r.id===id)||first;
  const agencyColor=agency=>agency==='ktmb'?'#f85149':agency.startsWith('prasarana')?'#58a6ff':'#3fb950';
  function buttons(){document.getElementById('region-list').innerHTML=config.regions.map(r=>'<button class="region-btn '+(r.id===current?'active':'')+'" data-region="'+r.id+'">'+r.label+'</button>').join('');document.querySelectorAll('.region-btn').forEach(b=>b.onclick=()=>switchRegion(b.dataset.region))}
  function clear(){Object.values(markers).forEach(m=>map.removeLayer(m));Object.keys(markers).forEach(k=>delete markers[k])}
  function apply(list){const seen=new Set();list.forEach(v=>{seen.add(v.id);if(markers[v.id])markers[v.id].setLatLng([v.lat,v.lng]);else markers[v.id]=L.circleMarker([v.lat,v.lng],{radius:5,color:agencyColor(v.agency),fillOpacity:.85}).addTo(map).bindPopup(v.agency+' — '+(v.route||v.id))});Object.keys(markers).forEach(id=>{if(!seen.has(id)){map.removeLayer(markers[id]);delete markers[id]}})}
  function render(d){const c=document.getElementById('catalog'),n=document.getElementById('catalog-notes'),e=document.getElementById('catalog-empty');c.innerHTML='';n.innerHTML='';e.textContent=d.empty?(d.message||'No snapshot data for this region.'):'';(d.notes||[]).forEach(x=>{const li=document.createElement('li');li.textContent=x;n.appendChild(li)});(d.agencies||[]).forEach(a=>{const b=document.createElement('div');b.className='catalog-agency';b.innerHTML='<h3>'+a.agency+' ('+a.count+')</h3>';(a.snapshots||[]).slice(0,8).forEach(s=>{const row=document.createElement('div');row.className='snap-row';row.textContent=(s.at?new Date(s.at).toISOString():'—')+' · '+s.source+' · '+s.s3Key;b.appendChild(row)});c.appendChild(b)})}
  async function catalog(){const s=document.getElementById('replay-status'),r=await fetch('/api/replay/catalog?region='+encodeURIComponent(current));if(!r.ok){s.textContent='Catalog failed';s.className='status err';return}const d=await r.json();render(d);s.textContent=d.empty?'No snapshots to replay.':'Loaded '+d.total+' snapshot(s). Press Play.';s.className=d.empty?'status err':'status ok'}
  async function switchRegion(id){current=id;const r=region(id);document.getElementById('region-subtitle').textContent=r.label;buttons();map.flyTo(r.center,r.zoom,{duration:.8});clear();stop();await catalog()}
  function stop(){if(source){source.close();source=null}document.getElementById('btn-play').disabled=false;document.getElementById('btn-stop').disabled=true}
  function play(){stop();const s=document.getElementById('replay-status'),speed=document.getElementById('speed').value;source=new EventSource('/api/replay/stream?region='+encodeURIComponent(current)+'&speed='+speed);document.getElementById('btn-play').disabled=true;document.getElementById('btn-stop').disabled=false;source.addEventListener('vehicles',e=>apply(JSON.parse(e.data)));source.addEventListener('progress',e=>{const p=JSON.parse(e.data);if(p.status!=='starting'){s.textContent='Frame '+p.frame+' / '+p.total+(p.at?' · '+p.at:'');s.className='status ok'}});source.addEventListener('done',()=>{s.textContent='Replay complete.';stop()});source.addEventListener('error',e=>{if(e.data){try{const err=JSON.parse(e.data);s.textContent=err.message||'Replay error'}catch(_){s.textContent='Replay error'}}else s.textContent='Replay error';s.className='status err';stop()});source.onerror=()=>{if(source&&source.readyState===EventSource.CLOSED)stop()}}
  document.getElementById('btn-play').onclick=play;document.getElementById('btn-stop').onclick=stop;document.getElementById('region-subtitle').textContent=first.label;buttons();catalog();
})()`

const schemaSQL = `CREATE TABLE IF NOT EXISTS sessions (session_id TEXT PRIMARY KEY, region_id TEXT NOT NULL, poll_seconds INTEGER NOT NULL DEFAULT 10, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS vehicle_positions (vehicle_key TEXT PRIMARY KEY, agency TEXT NOT NULL, vehicle_id TEXT NOT NULL, region_id TEXT NOT NULL, lat REAL NOT NULL, lng REAL NOT NULL, route TEXT NOT NULL DEFAULT '', speed REAL NOT NULL DEFAULT 0, bearing REAL NOT NULL DEFAULT 0, vehicle_group TEXT NOT NULL DEFAULT '', timestamp_ms INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ingest_events (id TEXT PRIMARY KEY, agency TEXT NOT NULL, region_id TEXT NOT NULL, vehicle_id TEXT NOT NULL, lat REAL NOT NULL, lng REAL NOT NULL, occurred_at INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS snapshots (id TEXT PRIMARY KEY, agency TEXT NOT NULL, region_id TEXT NOT NULL, source TEXT NOT NULL, r2_key TEXT NOT NULL, at_ms INTEGER NOT NULL, watermark_ns INTEGER NOT NULL DEFAULT 0, size INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS poll_state (id INTEGER PRIMARY KEY CHECK (id = 1), last_poll_ms INTEGER NOT NULL DEFAULT 0, event_count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS region_poll_state (region_id TEXT PRIMARY KEY, last_poll_ms INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_positions_region_agency ON vehicle_positions(region_id, agency);
CREATE INDEX IF NOT EXISTS idx_ingest_region_created ON ingest_events(region_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_snapshots_region_at ON snapshots(region_id, at_ms);
INSERT OR IGNORE INTO poll_state(id) VALUES (1);`

