const readmeMD = `# Gedung Peristiwa — Codex Sites bundle

Generated by go run ./cmd/codex-sites. The codex-sites/ directory is disposable and ignored by git.

This is a Cloudflare Worker version of the current transit UI. It keeps the existing browser API contract, but uses D1 for sessions, latest vehicle projections, ingest records, poll counters, and replay catalog rows; and R2 for immutable JSON ingest batches and replay payloads. R2 is the MinIO replacement for this generated deployment.

Live updates use short-lived fetches (Workers-friendly) instead of a long-lived EventSource. GTFS polling: one region per POST /api/poll, feeds fetched serially in AllFeeds() order, HTTP 429 retry with exponential backoff (1s initial, 30s max). Session interval 10/20/30s; auto-polls skip inside that window; pause while the tab is hidden. Replay rejects unknown region ids with HTTP 400.

## Generate and deploy

    go run ./cmd/codex-sites
    cd codex-sites
    npx wrangler d1 create gedung-peristiwa
    # Put the returned database_id in wrangler.jsonc
    npx wrangler d1 execute gedung-peristiwa --remote --file=schema.sql
    npx wrangler secret put INGEST_TOKEN
    npx wrangler deploy

The generated Worker expects D1 and R2 bindings named DB and EVENTS. POST /api/poll fetches the current region's GTFS-Realtime protobuf feeds from api.data.gov.my one feed at a time, decodes vehicle positions, writes the batch to R2, and updates the D1 projection. The live page polls automatically at the session interval; Poll GTFS → R2 forces an immediate refresh (2s claim gap). POST /api/ingest remains available for trusted producers; set INGEST_TOKEN to protect it.

This is an isolated deployment target. It does not alter or import the existing IsleDB/MinIO runtime. Re-run the compiler when Go region/feed catalog changes; edit internal/codexsites/templates.go when poller or UI behaviour changes (see AGENTS.md).
`

const workerTS = `type Region = { id:string; label:string; center:[number,number]; zoom:number; agencies:string[] };
type Feed = { agency:string; region:string; group:string; url:string };
type Position = { id:string; lat:number; lng:number; agency:string; group?:string; route?:string; speed?:number; bearing?:number; timestamp?:string };
type Env = { DB:D1Database; EVENTS:R2Bucket; ASSETS:Fetcher; INGEST_TOKEN?:string; SITE_NAME?:string };

const SITE_DATA = __REGIONS_JSON__;
const REGIONS:Region[] = SITE_DATA.regions;
const FEEDS:Feed[] = SITE_DATA.feeds;
const ALLOWED_POLL = [10,20,30];
const DEFAULT_POLL = 10;
const knownRegion = (id:string) => REGIONS.find(r=>r.id===id);
const regionByID = (id:string) => knownRegion(id) ?? REGIONS[0];
const json = (value:unknown, init:ResponseInit={}) => new Response(JSON.stringify(value),{...init,headers:{'content-type':'application/json; charset=utf-8',...(init.headers||{})}});
const now = () => Date.now();
const cookieID = (request:Request) => request.headers.get('Cookie')?.match(/(?:^|;\s*)demo_sid=([^;]+)/)?.[1] || crypto.randomUUID();
const withCookie = (response:Response, sid:string) => { const h=new Headers(response.headers);h.append('Set-Cookie','demo_sid='+sid+'; Path=/; HttpOnly; SameSite=Lax; Secure');return new Response(response.body,{status:response.status,headers:h}) };
const agenciesFor = (id:string) => new Set(regionByID(id).agencies);
const feedsFor = (id:string) => { const allowed=agenciesFor(id); return FEEDS.filter(f=>allowed.has(f.agency)).map(f=>({agency:f.agency,region:f.region})) };
const sse = (event:string,data:unknown) => 'event: '+event+'\ndata: '+JSON.stringify(data)+'\n\n';
const sleep = (ms:number) => new Promise<void>(resolve=>setTimeout(resolve,ms));
const normalizePoll = (n:number) => ALLOWED_POLL.includes(n) ? n : 0;
function backoffMs(attempt:number){const d=1000*Math.pow(2,attempt);return d>30000?30000:d}
function gtfsFeedsFor(regionID:string){const allowed=new Set(knownRegion(regionID)?.agencies||[]);return FEEDS.filter(f=>allowed.has(f.agency))}
async function claimRegionPoll(env:Env,regionID:string,force:boolean,pollSeconds:number){
  const t=now(),gap=force?2000:pollSeconds*1000;
  const result=await env.DB.prepare('INSERT INTO region_poll_state(region_id,last_poll_ms) VALUES(?,?) ON CONFLICT(region_id) DO UPDATE SET last_poll_ms=excluded.last_poll_ms WHERE excluded.last_poll_ms-region_poll_state.last_poll_ms>=?').bind(regionID,t,gap).run();
  return Number(result.meta?.changes??1)>0;
}
async function fetchFeed(feed:Feed){
  let lastError='';
  for(let attempt=0;attempt<4;attempt++){
    try{
      const response=await fetch(feed.url,{signal:AbortSignal.timeout(30000)});
      if(response.status===429){lastError='HTTP 429';await sleep(backoffMs(attempt));continue}
      if(!response.ok)return{feed,positions:[] as Position[],error:'HTTP '+response.status};
      return{feed,positions:decodeGTFS(await response.arrayBuffer(),feed),error:''};
    }catch(error){
      lastError=error instanceof Error?error.message:'fetch failed';
      break;
    }
  }
  return{feed,positions:[] as Position[],error:lastError};
}
async function pollFeedsSequential(feeds:Feed[]){
  const results:{feed:Feed;positions:Position[];error:string}[]=[];
  for(const feed of feeds)results.push(await fetchFeed(feed));
  return results;
}
function regionPayload(id:string){const r=regionByID(id);return{id:r.id,label:r.label,center:r.center,zoom:r.zoom,agencies:r.agencies}}
function readVarint(bytes:Uint8Array,offset:number){let value=0,shift=0;while(offset<bytes.length){const b=bytes[offset++];value+=(b&127)*Math.pow(2,shift);if(!(b&128))return{value,offset};shift+=7}return{value,offset}}
function protoFields(bytes:Uint8Array){const out:{field:number;wire:number;value:number|Uint8Array}[]=[];let offset=0;while(offset<bytes.length){const tag=readVarint(bytes,offset);offset=tag.offset;const field=Math.floor(tag.value/8),wire=tag.value&7;if(wire===0){const v=readVarint(bytes,offset);offset=v.offset;out.push({field,wire,value:v.value})}else if(wire===1){out.push({field,wire,value:bytes.slice(offset,offset+8)});offset+=8}else if(wire===2){const length=readVarint(bytes,offset);offset=length.offset;out.push({field,wire,value:bytes.slice(offset,offset+length.value)});offset+=length.value}else if(wire===5){out.push({field,wire,value:bytes.slice(offset,offset+4)});offset+=4}else break}return out}
function textField(bytes:Uint8Array,field:number){const hit=protoFields(bytes).find(f=>f.field===field&&f.wire===2);return hit?new TextDecoder().decode(hit.value as Uint8Array):''}
function bytesField(bytes:Uint8Array,field:number){const hit=protoFields(bytes).find(f=>f.field===field&&f.wire===2);return hit?.value as Uint8Array|undefined}
function floatField(bytes:Uint8Array,field:number){const hit=protoFields(bytes).find(f=>f.field===field&&f.wire===5);return hit?new DataView((hit.value as Uint8Array).buffer,(hit.value as Uint8Array).byteOffset,4).getFloat32(0,true):0}
function decodeGTFS(bytes:ArrayBuffer,feed:Feed){const data=new Uint8Array(bytes),positions:Position[]=[];for(const entity of protoFields(data).filter(f=>f.field===2&&f.wire===2)){const entityBytes=entity.value as Uint8Array,entityID=textField(entityBytes,1),vehicleBytes=bytesField(entityBytes,4);if(!vehicleBytes)continue;const positionBytes=bytesField(vehicleBytes,2);if(!positionBytes)continue;const lat=floatField(positionBytes,1),lng=floatField(positionBytes,2);if(lat<1||lat>7||lng<100||lng>119)continue;const vehicleDescriptor=bytesField(vehicleBytes,8),vehicleID=vehicleDescriptor?(textField(vehicleDescriptor,1)||textField(vehicleDescriptor,2)):entityID;if(!vehicleID)continue;const tripBytes=bytesField(vehicleBytes,1),timestampField=protoFields(vehicleBytes).find(f=>f.field===5&&f.wire===0);const timestamp=timestampField?new Date(Number(timestampField.value)*1000).toISOString():new Date().toISOString();positions.push({id:feed.agency+':'+vehicleID,agency:feed.agency,group:feed.group,lat,lng,bearing:floatField(positionBytes,3),speed:floatField(positionBytes,5),route:tripBytes?textField(tripBytes,5):'',timestamp})}return positions}

async function ensureSchema(env:Env){try{await env.DB.prepare('ALTER TABLE sessions ADD COLUMN poll_seconds INTEGER NOT NULL DEFAULT 10').run()}catch{}await env.DB.prepare('CREATE TABLE IF NOT EXISTS region_poll_state (region_id TEXT PRIMARY KEY, last_poll_ms INTEGER NOT NULL DEFAULT 0)').run()}
async function session(request:Request,env:Env){await ensureSchema(env);const sid=cookieID(request);const row=await env.DB.prepare('SELECT region_id,poll_seconds FROM sessions WHERE session_id=?').bind(sid).first<{region_id:string,poll_seconds:number}>();const regionID=row?.region_id||REGIONS[0].id;const pollSeconds=normalizePoll(Number(row?.poll_seconds||0))||DEFAULT_POLL;if(!row)await env.DB.prepare('INSERT INTO sessions(session_id,region_id,poll_seconds,updated_at) VALUES(?,?,?,?)').bind(sid,regionID,pollSeconds,now()).run();else await env.DB.prepare('UPDATE sessions SET updated_at=? WHERE session_id=?').bind(now(),sid).run();return{sid,regionID,pollSeconds}}
async function latest(env:Env,regionID:string){const ids=[...agenciesFor(regionID)];if(!ids.length)return[];const marks=ids.map(()=>'?').join(',');const rows=await env.DB.prepare('SELECT vehicle_key id,lat,lng,agency,vehicle_group group_name,route,speed,bearing,timestamp_ms FROM vehicle_positions WHERE agency IN ('+marks+') ORDER BY vehicle_key').bind(...ids).all<any>();return rows.results.map((v:any)=>({id:v.id,lat:v.lat,lng:v.lng,agency:v.agency,group:v.group_name,route:v.route,speed:v.speed,bearing:v.bearing,timestamp:new Date(v.timestamp_ms).toISOString()}))}
async function stats(env:Env,regionID:string,pollSeconds:number){const ids=[...agenciesFor(regionID)];const marks=ids.map(()=>'?').join(',');const count=ids.length?await env.DB.prepare('SELECT COUNT(*) count FROM vehicle_positions WHERE agency IN ('+marks+')').bind(...ids).first<{count:number}>():{count:number}|null;const p=await env.DB.prepare('SELECT last_poll_ms,event_count FROM poll_state WHERE id=1').first<{last_poll_ms:number,event_count:number}>();const rows=await env.DB.prepare('SELECT agency,vehicle_id vehicle,lat,lng,occurred_at at FROM ingest_events WHERE region_id=? ORDER BY created_at DESC LIMIT 10').bind(regionID).all<any>();const records=(rows.results||[]).map((r:any)=>({agency:r.agency,vehicle:r.vehicle,lat:r.lat,lng:r.lng,at:r.at?new Date(r.at).toISOString():'—'}));return{vehicleCount:Number(count?.count||0),lastUpdate:p?.last_poll_ms?new Date(p.last_poll_ms).toISOString():null,eventCount:Number(p?.event_count||0),pollSeconds,activeLabel:regionByID(regionID).label,polledAgencies:[...new Set(records.map((r:any)=>r.agency))],records}}
async function ingest(env:Env,request:Request){if(env.INGEST_TOKEN&&request.headers.get('Authorization')!=='Bearer '+env.INGEST_TOKEN)return json({error:'unauthorized'},{status:401});const body=await request.json() as {at?:string;positions?:Position[];polledAgencies?:string[]};const positions=Array.isArray(body.positions)?body.positions:[];const at=body.at?Date.parse(body.at):now();const batchID=at+'-'+crypto.randomUUID();const r2Key='events/'+batchID+'.json';await env.EVENTS.put(r2Key,JSON.stringify({at:new Date(at).toISOString(),positions,polledAgencies:body.polledAgencies||[]} ),{httpMetadata:{contentType:'application/json'}});const statements=[];const regionAgencies=new Map<string,Set<string>>();for(const v of positions){const r=REGIONS.find(x=>x.agencies.includes(v.agency));if(!r||!v.id)continue;if(!regionAgencies.has(r.id))regionAgencies.set(r.id,new Set<string>());regionAgencies.get(r.id)!.add(v.agency);const ts=v.timestamp?Date.parse(v.timestamp):at;statements.push(env.DB.prepare('INSERT INTO vehicle_positions(vehicle_key,agency,vehicle_id,region_id,lat,lng,route,speed,bearing,vehicle_group,timestamp_ms,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(vehicle_key) DO UPDATE SET lat=excluded.lat,lng=excluded.lng,route=excluded.route,speed=excluded.speed,bearing=excluded.bearing,timestamp_ms=excluded.timestamp_ms,updated_at=excluded.updated_at').bind(v.id,v.agency,v.id.split(':').slice(1).join(':')||v.id,r.id,Number(v.lat),Number(v.lng),v.route||'',Number(v.speed||0),Number(v.bearing||0),v.group||'',ts,now()));statements.push(env.DB.prepare('INSERT INTO ingest_events(id,agency,region_id,vehicle_id,lat,lng,occurred_at,created_at) VALUES(?,?,?,?,?,?,?,?)').bind(batchID+':'+v.id,v.agency,r.id,v.id,Number(v.lat),Number(v.lng),ts,now()))}for(const [regionID,agencies] of regionAgencies){for(const agency of agencies)statements.push(env.DB.prepare('INSERT INTO snapshots(id,agency,region_id,source,r2_key,at_ms,watermark_ns,size) VALUES(?,?,?,?,?,?,?,?)').bind(batchID+':'+agency,agency,regionID,'r2',r2Key,at,at*1000000,0))}statements.push(env.DB.prepare('INSERT INTO poll_state(id,last_poll_ms,event_count) VALUES(1,?,?) ON CONFLICT(id) DO UPDATE SET last_poll_ms=excluded.last_poll_ms,event_count=poll_state.event_count+excluded.event_count').bind(at,positions.length));for(let i=0;i<statements.length;i+=90)await env.DB.batch(statements.slice(i,i+90));return json({accepted:positions.length,r2Key})}
async function catalog(env:Env,regionID:string){const r=knownRegion(regionID);if(!r)return json({error:'unknown region'},{status:400});const rows=await env.DB.prepare('SELECT agency,id,source,r2_key s3Key,at_ms,watermark_ns FROM snapshots WHERE region_id=? ORDER BY at_ms DESC').bind(regionID).all<any>();const grouped=new Map<string,any[]>();for(const row of rows.results){const list=grouped.get(row.agency)||[];list.push({agency:row.agency,id:row.id,source:row.source,s3Key:row.s3Key,at:row.at_ms?new Date(row.at_ms).toISOString():null,watermarkNS:row.watermark_ns});grouped.set(row.agency,list)}const agencies=r.agencies.map(agency=>({agency,count:(grouped.get(agency)||[]).length,snapshots:grouped.get(agency)||[]}));const total=agencies.reduce((n,a)=>n+a.count,0);return json({regionId:regionID,label:r.label,empty:total===0,message:total===0?'No snapshot data for this region.':undefined,total,agencies,notes:['Snapshots are immutable R2 ingest batches indexed by D1.']})}
async function pollGTFS(env:Env,regionID:string,force:boolean,pollSeconds:number){if(!knownRegion(regionID))return json({error:'unknown region'},{status:400});if(!await claimRegionPoll(env,regionID,force,pollSeconds))return json({accepted:0,feeds:0,skipped:true,r2Key:null,errors:[],pollSeconds});const feeds=gtfsFeedsFor(regionID);const results=await pollFeedsSequential(feeds);const positions=results.flatMap(result=>result.positions);const body={at:new Date().toISOString(),positions,polledAgencies:feeds.map(feed=>feed.agency)};const headers=new Headers({'content-type':'application/json'});if(env.INGEST_TOKEN)headers.set('Authorization','Bearer '+env.INGEST_TOKEN);const stored=await ingest(env,new Request('https://internal/api/ingest',{method:'POST',headers,body:JSON.stringify(body)}));const storedBody=await stored.json() as {r2Key?:string};await env.DB.prepare('INSERT INTO region_poll_state(region_id,last_poll_ms) VALUES(?,?) ON CONFLICT(region_id) DO UPDATE SET last_poll_ms=excluded.last_poll_ms').bind(regionID,now()).run();return json({accepted:positions.length,feeds:feeds.length,r2Key:storedBody.r2Key,errors:results.filter(result=>result.error).map(result=>({agency:result.feed.agency,error:result.error})),pollSeconds,skipped:false})}
async function replayStream(env:Env,regionID:string,speed:number){const r=knownRegion(regionID);if(!r)return json({error:'unknown region'},{status:400});const encoder=new TextEncoder();const rows=await env.DB.prepare('SELECT DISTINCT r2_key,at_ms FROM snapshots WHERE region_id=? ORDER BY at_ms ASC').bind(regionID).all<any>();return new Response(new ReadableStream({start(controller){const run=async()=>{try{controller.enqueue(encoder.encode(sse('progress',{frame:0,total:rows.results.length,status:'starting'})));const merged=new Map<string,Position>();for(let i=0;i<rows.results.length;i++){const object=await env.EVENTS.get(rows.results[i].r2_key);if(object){const batch=JSON.parse(await object.text()) as {positions:Position[]};for(const p of batch.positions||[])merged.set(p.id,p)}controller.enqueue(encoder.encode(sse('vehicles',[...merged.values()].filter(p=>agenciesFor(regionID).has(p.agency)))));controller.enqueue(encoder.encode(sse('progress',{frame:i+1,total:rows.results.length,at:rows.results[i].at_ms?new Date(rows.results[i].at_ms).toISOString():null,status:'playing'})));if(i+1<rows.results.length)await sleep(Math.max(0,1000/Math.max(1,speed)))}controller.enqueue(encoder.encode(sse('done',{status:'complete'})));controller.close()}catch(error){try{controller.enqueue(encoder.encode(sse('error',{message:error instanceof Error?error.message:'replay failed'})));controller.close()}catch{}}};void run()}}),{headers:{'content-type':'text/event-stream','cache-control':'no-cache','connection':'keep-alive'}})}

export default {async fetch(request:Request,env:Env):Promise<Response>{const url=new URL(request.url),path=url.pathname;try{if(path==='/api/ingest'&&request.method==='POST')return ingest(env,request);const {sid,regionID,pollSeconds}=await session(request,env);if(path==='/api/poll'&&request.method==='POST')return withCookie(await pollGTFS(env,url.searchParams.get('region')||regionID,url.searchParams.get('force')==='1',pollSeconds),sid);if(path==='/api/poll-interval'){if(request.method==='POST'){const body=await request.json() as {seconds:number};const next=normalizePoll(Number(body.seconds));if(!next)return json({error:'poll interval must be 10, 20, or 30 seconds'},{status:400});await env.DB.prepare('UPDATE sessions SET poll_seconds=?,updated_at=? WHERE session_id=?').bind(next,now(),sid).run();return withCookie(json({seconds:next,options:ALLOWED_POLL}),sid)}if(request.method!=='GET')return json({error:'method not allowed'},{status:405});return withCookie(json({seconds:pollSeconds,options:ALLOWED_POLL}),sid)}if(path==='/api/regions')return withCookie(json({active:regionID,regions:REGIONS.map(r=>({...regionPayload(r.id),active:r.id===regionID}))}),sid);if(path==='/api/region'){if(request.method==='POST'){const body=await request.json() as {id:string};if(!knownRegion(body.id))return json({error:'unknown region'},{status:400});await env.DB.prepare('UPDATE sessions SET region_id=?,updated_at=? WHERE session_id=?').bind(body.id,now(),sid).run();return withCookie(json({region:regionPayload(body.id),feeds:feedsFor(body.id),pollSeconds}),sid)}return withCookie(json({region:regionPayload(regionID),feeds:feedsFor(regionID),pollSeconds}),sid)}if(path==='/api/vehicles')return withCookie(json(await latest(env,regionID)),sid);if(path==='/api/status')return withCookie(json(await stats(env,regionID,pollSeconds)),sid);if(path==='/api/replay/catalog')return withCookie(await catalog(env,url.searchParams.get('region')||regionID),sid);if(path==='/api/replay/stream'){const wanted=url.searchParams.get('region')||regionID;if(!knownRegion(wanted))return withCookie(json({error:'unknown region'},{status:400}),sid);return withCookie(await replayStream(env,wanted,Number(url.searchParams.get('speed')||1)),sid)}const assetPath=path==='/'?'/index.html':path==='/replay'?'/replay.html':path;return env.ASSETS.fetch(new Request(new URL(assetPath,url),request))}catch(error){return json({error:error instanceof Error?error.message:'request failed'},{status:500})}}};
`
